/**
 * IMAGE REGISTRY
 * ---------------------------------------------------------------------------
 * All site imagery is referenced by key from here, so photos can be swapped
 * without touching components.
 *
 * The files in /public/images/products are ORIGINAL, unbranded 3D studio
 * renders generated by `scripts/renders` (Blender). They are representative
 * of each product type and carry no third-party licensing restrictions.
 *
 * To use real photography: drop a file into /public/images/… and change the
 * `src` below (keep 4:3 ratio, transparent or light background, ≥1000px wide).
 * Product-specific photos go on the product itself (product.images) and always
 * take priority over these representative images.
 */
import type { CategorySlug, DeviceArtKind, Product } from './types'

export interface Media {
  src: string
  alt: string
  width: number
  height: number
  /** Fallback illustration if the file fails to load. */
  art: DeviceArtKind
}

/** Base path for image files ('/' in production; './' for the single-file preview build). */
export const IMG_BASE = import.meta.env.VITE_IMAGE_BASE || '/'

const r = (file: string, alt: string, art: DeviceArtKind, w = 1000, h = 750): Media => ({
  src: `${IMG_BASE}images/products/${file}.webp`,
  alt,
  width: w,
  height: h,
  art,
})

/** Transparent cut-outs of PeopleLink product photos from the supplied presentation (dark products only). */
const av = (file: string, alt: string, w: number, h: number): Media => ({
  src: `${IMG_BASE}images/audio-video/cutouts/${file}.webp`,
  alt,
  width: w,
  height: h,
  art: 'monitor',
})

