export type MediaKey = keyof typeof media

export const categoryMedia: Record<CategorySlug, MediaKey> = {
  'new-laptops': 'laptopSilver',
  'refurbished-laptops': 'laptopBlack',
  'desktops-workstations': 'desktopTower',
  'apple-products': 'smartphones',
  'monitors-displays': 'monitor',
  'printers-scanners': 'printer',
  'it-accessories': 'keyboardMouse',
  'components-parts': 'ssdRam',
  networking: 'router',
  'servers-storage': 'server',
  'headsets-audio-solutions': 'headsetStereo',
}

/** Chooses a representative image for a product without its own photos. */
export function productMediaKey(p: Product): MediaKey {
  if (p.imageKey) return p.imageKey
  const t = `${p.name} ${p.subcategory ?? ''}`.toLowerCase()
  if (p.category === 'new-laptops' || p.category === 'refurbished-laptops') {
    if (/legion|performance|gaming/.test(t)) return 'laptopPerformance'
    if (/macbook|xps|premium|elitebook 840 g11/.test(t)) return 'laptopGrey'
    if (/thinkpad|latitude 7|used/.test(t)) return 'laptopBlack'
    return 'laptopSilver'
  }
  if (p.category === 'desktops-workstations') {
    if (/mini/.test(t)) return 'miniPc'
    if (/all-in-one|aio/.test(t)) return 'allInOne'
    return 'desktopTower'
  }
  if (p.category === 'apple-products') {
    if (/macbook/.test(t)) return 'laptopGrey'
    if (/imac/.test(t)) return 'allInOne'
    if (/mac mini/.test(t)) return 'miniPc'
    if (/iphone/.test(t)) return 'smartphones'
    if (/airpods/.test(t)) return 'earbuds'
    if (/watch/.test(t)) return 'smartwatch'
    if (/magsafe|wireless charger/.test(t)) return 'wirelessCharger'
    if (/adapter|charger/.test(t)) return 'charger'
    if (/keyboard|mouse|trackpad/.test(t)) return 'keyboardMouse'
    if (/cable/.test(t)) return 'cables'
    return 'tablet'
  }
  if (p.category === 'it-accessories') {
    if (/keyboard|mouse/.test(t)) return 'keyboardMouse'
    if (/charger|adapter/.test(t)) return 'charger'
    if (/dock|hub/.test(t)) return 'dock'
    if (/headset|webcam/.test(t)) return /webcam/.test(t) ? 'webcam' : 'headset'
    if (/stand/.test(t)) return 'laptopStand'
    if (/cable/.test(t)) return 'cables'
    return 'keyboardMouse'
  }
  if (p.category === 'components-parts') {
    if (/external/.test(t)) return 'externalDrive'
    if (/battery|replacement/.test(t)) return 'batteryParts'
    return 'ssdRam'
  }
  if (p.category === 'networking') {
    if (/switch/.test(t)) return 'switch'
    if (/access point/.test(t)) return 'accessPoint'
    if (/firewall/.test(t)) return 'firewall'
    return 'router'
  }
  if (p.category === 'headsets-audio-solutions') {
    if (/speakerphone|sync|speak2|meeting/.test(t)) return 'speakerphone'
    if (/accessor|cushion|adapter|cable/.test(t)) return 'headsetAccessories'
    if (/wireless|bluetooth|voyager|evolve2 65|zone vibe|730/.test(t)) return 'headsetWireless'
    if (/call centre|encorepro|engage|mono/.test(t)) return 'headsetMono'
    return 'headsetStereo'
  }
  if (p.category === 'monitors-displays') return /signage|interactive/.test(t) ? 'signage' : 'monitor'
  if (p.category === 'servers-storage') return /nas|storage/.test(t) ? 'externalDrive' : 'server'
  return categoryMedia[p.category]
}
